query PullRequestForBranch($owner: String!, $repo: String!, $headRefName: String!, $states: [PullRequestState!]) {
	repository(owner: $owner, name: $repo) {
		pullRequests(headRefName: $headRefName, states: $states, first: 30, orderBy: { field: CREATED_AT, direction: DESC }) {
			nodes {number,title,body,state,headRefName,baseRefName,additions,deletions,changedFiles,files(first: 100) {nodes {additions,deletions,path,changeType}},commits(first: 100) {nodes {commit {authors(first:100) {nodes {name,email,user{id,login}}},messageHeadline,messageBody,oid,committedDate,authoredDate}}},reviewDecision,mergeable,url,id,isCrossRepository,headRepositoryOwner{id,login,...on User{name}}}
		}
		defaultBranchRef { name }
	}
}
